const canvas = document.createElement('canvas');
canvas.width = GRID_WIDTH;
canvas.height = GRID_HEIGHT;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const EMOJIS = [
  '\u{1F308}', '\u{1F307}', '\u{1F306}', '\u{1F305}',
  '\u{1F535}', '\u{1F52E}', '\u{1F52D}', '\u{1F52C}',
  '\u{1F52B}', '\u{1F52A}', '\u{1F529}', '\u{1F528}'
];

let grid = Array.from({ length: GRIDY }, () => new Array(GRIDX).fill(false));
let nextGrid = Array.from({ length: GRIDY }, () => new Array(GRIDX).fill(false));
let generation = 0;
let speed = 5;

function drawGrid() {
  ctx.canvas.width = GRID_WIDTH; 
  for (let y = 0; y < GRIDY; y++) {
    for (let x = 0; x < GRIDX; x++) {
      ctx.fillStyle = grid[y][x] ? '#000' : '#fff';
      ctx.fillText(EMOJIS[getEmojiIndex(y, x)], x * CELL_SIZE, y * CELL_SIZE);
    }
  }
}

function getEmojiIndex(x, y) {
  let aliveNeighbors = 0;
  for (let i = -1; i <= 1; i++) {
    for (let j = -1; j <= 1; j++) {
      if (grid[prependZero(y + i) / 10][prependZero(x + j) / 10]) {
        aliveNeighbors++;
      }
    }
  }
  return grid[y][x] ? aliveNeighbors === 2 || aliveNeighbors === 3 ? aliveNeighbors - 2 : 0 : aliveNeighbors === 3 ? 1 : 0;
}

function prependZero(num) {
  return Number(num).toString().padStart(2, '0');
}

function toggleCell(event) {
  const x = Math.floor(event.x / CELL_SIZE);
  const y = Math.floor(event.y / CELL_SIZE);
  grid[y][x] = !grid[y][x];
}

function getNeighborCount(x, y) {
  let count = 0;
  for (let i = -1; i <= 1; i++) {
    for (let j = -1; j <= 1; j++) {
      if (grid[y + i][x + j]) {
        count++;
      }
    }
  }
  if (grid[y][x]) {
    count--;
  }
  return count;
}

function update() {
  generation++;
  for (let y = 0; y < GRIDY; y++) {
    for (let x = 0; x < GRIDX; x++) {
      nextGrid[y][x] = grid[y][x];
    }
  }
  for (let y = 0; y < GRIDY; y++) {
    for (let x = 0; x < GRIDX; x++) {
      let neighborCount = getNeighborCount(x, y);
      if (neighborCount < 2 || neighborCount > 3) {
        nextGrid[y][x] = false;
      } else if (grid[y][x]) {
        nextGrid[y][x] = true;
      }
    }
  }
  grid = nextGrid.map(row => [...row]);
  drawGrid();
}

